let HF_SELECTION=null,hfNext=null,hfGeneration=0,hfInspectGeneration=0,hfOptions=[];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repoPath=id=>id.split('/').map(encodeURIComponent).join('/');
async function hfJSON(url){const response=await fetch(url,{credentials:'omit',signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error(response.status===429?'Hugging Face rate limit reached. Please try again later.':`Hugging Face returned ${response.status}. The repository may be gated or unavailable.`);return {data:await response.json(),link:response.headers.get('Link')}}
function hfGroups(files){const groups=new Map();for(const f of files||[]){const name=f.rfilename||'';if(!/\.gguf$/i.test(name)||/mmproj|projector/i.test(name))continue;const match=name.match(/(?:^|[-_.])(Q3_K_M|Q4_0|Q4_K_M|Q5_K_M|Q6_K|Q8_0|F16|FP16)(?=[-_.]|$)/i);const shard=name.match(/-(\d{5})-of-(\d{5})\.gguf$/i);const key=shard?name.replace(/-\d{5}-of-\d{5}\.gguf$/i,'.gguf'):name;let g=groups.get(key);if(!g){g={name:key,quant:!match?'FILE':/^(F16|FP16)$/i.test(match[1])?'FP16':match[1].toUpperCase(),bytes:0,files:[],expected:shard?Number(shard[2]):1};groups.set(key,g)}g.files.push(name);const bytes=Number(f.size??f.lfs?.size);g.bytes=Number.isFinite(bytes)&&bytes>0&&g.bytes!==null?g.bytes+bytes:null;}return [...groups.values()].filter(g=>g.files.length===g.expected&&g.bytes>0)}
function hfState(s){const m=HF_SELECTION;if(m&&['params','quant','layers','heads','dim'].every(k=>s[k]===m[k]))return {...s,weightGiB:m.bytes/2**30};return s}
function renderHF(s){const m=HF_SELECTION;if(!m){$('hfActive').textContent='No model file loaded. Search above to select a GGUF, or explore with the controls below.';return}const active=['params','quant','layers','heads','dim'].every(k=>s[k]===m[k]);$('hfActive').textContent=active?`Loaded: ${m.repo} · ${m.name}. Weights use ${(m.bytes/2**30).toFixed(2)} GiB from published file sizes. ${m.confidence} GPU, reserve, offload, context, cache precision, and overhead remain adjustable.`:'Custom configuration: the searched file no longer matches your model controls. Select it again to reload.';}
async function hfSearch(more=false){const generation=++hfGeneration;const query=$('hfQuery').value.trim();const url=more?hfNext:`https://huggingface.co/api/models?filter=gguf&sort=downloads&direction=-1&limit=20&search=${encodeURIComponent(query)}`;if(!url)return;$('hfMore').hidden=true;$('hfStatus').textContent='Searching Hugging Face…';if(!more){$('hfResults').innerHTML='';$('hfFiles').innerHTML='';hfInspectGeneration++;}try{const {data,link}=await hfJSON(url);if(generation!==hfGeneration)return;if(!Array.isArray(data))throw Error('Unexpected search response.');const next=link?.match(/<([^>]+)>;\s*rel="next"/);hfNext=next&&next[1].startsWith('https://huggingface.co/api/models?')?next[1]:null;$('hfResults').insertAdjacentHTML('beforeend',data.map(m=>`<article class="hf-repo"><strong>${esc(m.id)}</strong><p>${esc(m.pipeline_tag||'Task not reported')} · ${Number(m.downloads||0).toLocaleString()} downloads · ${m.gated?'Access approval may be required':'Public listing'}</p><button data-hfrepo="${esc(m.id)}">Choose this model →</button> <a href="https://huggingface.co/${repoPath(m.id)}" target="_blank" rel="noreferrer">Model card ↗</a></article>`).join(''));$('hfStatus').textContent=data.length?`${data.length} repositories added, sorted by downloads—not quality. Choose a model, then select a GGUF file to calculate its fit.`:'No repositories found. Try a family name or publisher.';$('hfMore').hidden=!hfNext;}catch(e){if(generation===hfGeneration)$('hfStatus').textContent=`Search unavailable: ${e.message} You can still adjust the calculator controls manually.`;}}
async function hfInspect(repo){const generation=++hfInspectGeneration;$('hfFiles').textContent='Reading file sizes and architecture metadata…';hfOptions=[];try{const {data:m}=await hfJSON(`https://huggingface.co/api/models/${repoPath(repo)}?blobs=true`);let config=null,configSource=repo;let base=m.cardData?.base_model;if(Array.isArray(base))base=base[0];for(const candidate of [repo,typeof base==='string'?base:null].filter(Boolean)){try{const {data}=await hfJSON(`https://huggingface.co/${repoPath(candidate)}/resolve/main/config.json`);config=data.text_config||data;configSource=candidate;if(config.num_hidden_layers)break;}catch{}}
 if(generation!==hfInspectGeneration)return;const g=m.gguf||{};const params=Number(g.total||m.safetensors?.total)/1e9;const layers=Number(config?.num_hidden_layers),heads=Number(config?.num_key_value_heads??config?.num_attention_heads),dim=Number(config?.head_dim||(config?.hidden_size/config?.num_attention_heads));const architecture=config?.model_type||g.architecture;const verified=['llama','qwen2'].includes(architecture)&&!config?.use_sliding_window&&layers>0&&heads>0&&dim>0;const cap=Number(config?.max_position_embeddings||g.context_length);const groups=hfGroups(m.siblings);hfOptions=groups.map(f=>({...f,repo,params:Number.isFinite(params)&&params>=1?Math.round(params*100)/100:null,layers:verified?layers:null,heads:verified?heads:null,dim:verified?dim:null,cap:Number.isFinite(cap)&&cap>=2048?cap:null,verified}));
 $('hfFiles').innerHTML=`<h3 style="margin-top:24px">${esc(repo)}</h3><p class="note">${verified?'Full-attention cache dimensions read from configuration.':'Architecture is missing or outside the verified dense full-attention estimator. Generic cache assumptions will be used; fit is provisional, especially for MoE, hybrid attention, and multimodal models.'} Parameter count: ${Number.isFinite(params)?esc(params.toFixed(2))+'B from metadata':'not reported; your current parameter control will be retained'}. <a href="https://huggingface.co/${repoPath(configSource)}/blob/main/config.json" target="_blank" rel="noreferrer">Configuration source</a>. Check runtime compatibility and license on the model card.</p>`+(groups.length?`<label for="hfFileSelect">Select a GGUF file to calculate VRAM</label><select id="hfFileSelect"><option value="">Choose a file / quantization…</option>${hfOptions.map((f,i)=>`<option value="${i}">${esc(f.name)} · ${(f.bytes/2**30).toFixed(2)} GiB</option>`).join('')}</select><p class="note">Selecting a file immediately loads it into the calculator below. GPU capacity and reserve stay unchanged.</p>`+hfOptions.map((f,i)=>{const s=state();const r=estimate({...s,weightGiB:f.bytes/2**30,...(verified?{layers,heads,dim}:{})});return `<article class="hf-file"><strong>${esc(f.name)}</strong><p>${(f.bytes/2**30).toFixed(2)} GiB file weights · ${f.files.length} file(s)<br>${verified?'Estimated':'Provisional'} fit: ${esc(r.band)} · ${r.total.toFixed(1)} GiB VRAM at inspection time (${s.context/1024}K context, ${s.offload}% offload, ${s.vram} GiB GPU). Load to get a live forecast.<br>${f.cap&&s.context>f.cap?'Context exceeds reported limit; loading will reduce it.':''}</p><button data-hffile="${i}">Load into calculator</button> <a href="https://huggingface.co/${repoPath(repo)}/blob/main/${f.files[0].split('/').map(encodeURIComponent).join('/')}" target="_blank" rel="noreferrer">${f.files.length>1?'First shard · download all shards':'File details / download'} ↗</a></article>`}).join(''):'<p>No complete GGUF files with known sizes were found. Projector-only files and incomplete split sets are excluded. Inspect the model card for requirements.</p>');$('hfFiles').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){if(generation===hfInspectGeneration)$('hfFiles').textContent=`Could not inspect this repository: ${e.message}`}}
function hfLoad(index){const m=hfOptions[index];if(!m)return;selectedModel='';for(const key of ['params','layers','heads','dim']){if(m[key]!==null){if(key==='params')$('params').max=Math.max(72,Math.ceil(m.params));else $(key).max=Math.max(Number($(key).max)||0,m[key]);$(key).value=m[key]}}$('quant').value=m.quant;if(m.cap&&Number($('context').value)>m.cap){const choices=[2048,4096,8192,16384,32768,65536,131072].filter(n=>n<=m.cap);$('context').value=choices.at(-1)||2048;}HF_SELECTION={...m,...Object.fromEntries(['params','layers','heads','dim'].map(k=>[k,Number($(k).value)])),confidence:m.verified?'Architecture sourced from configuration; runtime allocation remains approximate.':'Provisional estimate using your current cache assumptions; verify advanced settings against model metadata.'};render();$('resultTitle').scrollIntoView({behavior:'smooth',block:'center'});}
if(typeof document!=='undefined'){
 document.getElementById('hfForm').onsubmit=e=>{e.preventDefault();hfSearch()};
 document.getElementById('hfMore').onclick=()=>hfSearch(true);
 document.getElementById('hfResults').onclick=e=>{const b=e.target.closest('[data-hfrepo]');if(b)hfInspect(b.dataset.hfrepo)};
 document.getElementById('hfFiles').onchange=e=>{if(e.target.id==='hfFileSelect'&&e.target.value!=='')hfLoad(Number(e.target.value))};
 document.getElementById('hfFiles').onclick=e=>{const b=e.target.closest('[data-hffile]');if(b)hfLoad(Number(b.dataset.hffile))};
}
if(typeof module!=='undefined')module.exports={hfGroups};
